draw:
function draw(ctx, t, W, H) {
  ctx.save();
  ctx.fillStyle = '#f5f0e8';
  ctx.fillRect(0, 0, W, H);

  // stalls
  ctx.fillStyle = '#ffd7be';
  ctx.fillRect(50, H/2 - 50, 100, 100);
  ctx.fillRect(W-150, H/2 - 50, 100, 100);

  // people
  ctx.fillStyle = '#ffffff';
  ctx.beginPath();
  ctx.arc(100, H/2, 20, 0, 2 * Math.PI);
  ctx.fill();
  ctx.beginPath();
  ctx.arc(W-100, H/2, 20, 0, 2 * Math.PI);
  ctx.fill();

  // market goods
  ctx.fillStyle = '#ff99cc';
  ctx.fillRect(70, H/2 - 20, 20, 20);
  ctx.fillStyle = '#ccff99';
  ctx.fillRect(W-120, H/2 - 20, 20, 20);

  // moving goods
  ctx.fillStyle = '#99ccff';
  ctx.fillRect(150 + 50 * Math.sin(t), H/2 - 50, 20, 20);
  ctx.fillStyle = '#ffcc99';
  ctx.fillRect(W-200 + 50 * Math.cos(t), H/2 - 50, 20, 20);

  // outlines
  ctx.strokeStyle = '#000000';
  ctx.lineWidth = 3;
  ctx.strokeRect(50, H/2 - 50, 100, 100);
  ctx.strokeRect(W-150, H/2 - 50, 100, 100);
  ctx.stroke();
  ctx.beginPath();
  ctx.arc(100, H/2, 20, 0, 2 * Math.PI);
  ctx.stroke();
  ctx.beginPath();
  ctx.arc(W-100, H/2, 20, 0, 2 * Math.PI);
  ctx.stroke();

  ctx.restore();
}
